<?php

declare(strict_types=1);

namespace App\Tools\SefazFiscalValidator\Presentation\Controllers; use App\Core\Access\Services\ToolFeatureRequestAuthorizer; use App\Http\Controllers\Controller; use App\Tools\SefazFiscalValidator\Tool; use App\Tools\SefazFiscalValidator\Application\Actions\CalculateTool; use App\Tools\SefazFiscalValidator\Application\Actions\ShowToolPage; use App\Tools\SefazFiscalValidator\Application\Data\CalculationInput; use App\Tools\SefazFiscalValidator\Presentation\Requests\ExecuteToolRequest; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; final class ToolController extends Controller { public function index(Request $request,ShowToolPage $page,ToolFeatureRequestAuthorizer $features,Tool $module):View{return view('tools-validador-fiscal-sefaz::index',[...$page->execute(),'keyBreakdownAllowed'=>$features->allows($module,'key_breakdown',$request)]);} public function calculate(ExecuteToolRequest $request,CalculateTool $action,ShowToolPage $page,ToolFeatureRequestAuthorizer $features,Tool $module):View{$d=$request->validated(); try{$r=$action->execute(new CalculationInput($d['access_key']));}catch(\InvalidArgumentException $e){return back()->withErrors(['access_key'=>$e->getMessage()])->withInput();}$request->flash();return view('tools-validador-fiscal-sefaz::index',[...$page->execute(),'result'=>$r,'keyBreakdownAllowed'=>$features->allows($module,'key_breakdown',$request)]);}}
